    #[test]
    fn live_card_grows_with_output_but_never_past_the_viewport() {
        // Idle prompt and a command that has printed nothing yet both sit on
        // the floor, so pressing Enter changes no height at all.
        assert_eq!(live_visible_rows(1, 40), 6);
        assert_eq!(live_visible_rows(6, 40), 6);
        // Then one row per row of output ...
        assert_eq!(live_visible_rows(7, 40), 7);
        assert_eq!(live_visible_rows(39, 40), 39);
        // ... up to the viewport, which is where the old code started.
        assert_eq!(live_visible_rows(40, 40), 40);
        assert_eq!(live_visible_rows(4000, 40), 40);
        // A pane too short for the floor still gets a card, never zero rows.
        assert_eq!(live_visible_rows(1, 3), 3);
        assert_eq!(live_visible_rows(9, 3), 3);
    }

    #[test]
    fn command_start_measurements_before_output_are_provisional() {
        // CommandStart resizes the full grid before VTE has necessarily
        // published a coherent adjustment. With no captured output yet, that
        // transient `None` keeps the compact card and does not poison the
        // command's high-water mark.
        assert_eq!(
            super::live_visible_rows_for_measurement(None, false, false, 6, 40),
            (6, 6)
        );
        // A coherent-looking extent can be from the old grid generation too.
        assert_eq!(
            super::live_visible_rows_for_measurement(Some(38), false, false, 6, 40),
            (6, 6)
        );
        // Preserve a multiline input baseline until actual output supersedes it.
        assert_eq!(
            super::live_visible_rows_for_measurement(Some(2), false, false, 9, 40),
            (9, 9)
        );
        // Bytes reach the capture ring before VTE settles its cursor and
        // adjustment, so a first-chunk None remains provisional too.
        let (visible, high_water) =
            super::live_visible_rows_for_measurement(None, true, false, 6, 40);
        assert_eq!((visible, high_water), (6, 6));
        assert_eq!(
            super::live_visible_rows_for_measurement(Some(8), true, false, high_water, 40),
            (8, 8)
        );

        // An explicit ED3/RIS barrier exposes the viewport and latches it; a
        // later coherent sample cannot shrink the card underneath that output.
        let (visible, high_water) =
            super::live_visible_rows_for_measurement(None, true, true, 6, 40);
        assert_eq!((visible, high_water), (40, 40));
        assert_eq!(
            super::live_visible_rows_for_measurement(Some(3), true, false, high_water, 40),
            (40, 40)
        );
    }

    #[test]
    fn live_card_measures_from_the_row_the_prompt_began_on() {
        // Prompt-phase samples: the shell draws a two-row prompt starting at
        // ring row 5000 (rows climb for the life of the pane — `vte.reset()`
        // never rewinds them), then echoes the command, leaving the cursor on
        // 5001. The origin is the FIRST row, not the last sample; taking the
        // last one is what hid an inline TUI's composer below the card.
        let mut origin = None;
        for row in [5000, 5001, 5001] {
            origin = Some(super::latched_live_origin(origin, row));
        }
        assert_eq!(origin, Some(5000));
        // Cursor parked in a composer 14 rows down: the card shows all 15.
        assert_eq!(live_content_extent_for(5000, 5014, 32), 15);
        // Output past the grid caps at the grid.
        assert_eq!(live_content_extent_for(5000, 9999, 32), 32);
        // A lower sample still wins while the prompt is drawing.
        assert_eq!(super::latched_live_origin(Some(5), 3), 3);
        assert_eq!(super::latched_live_origin(None, 7), 7);
    }

    #[test]
    fn the_compact_card_covers_whatever_the_shell_drew_at_the_prompt() {
        use super::{compact_card_rows, MIN_INPUT_ROWS};
        // An empty prompt keeps the warp-style floor, whatever it measured.
        assert_eq!(compact_card_rows(1, 1, 40), MIN_INPUT_ROWS as i64);
        assert_eq!(compact_card_rows(1, 3, 40), MIN_INPUT_ROWS as i64);
        // A completion menu below the input is the card's height now: it used
        // to be clipped to the floor with the rest of the pane left empty.
        assert_eq!(compact_card_rows(1, 29, 40), 29);
        // A multi-line command still counts, and the taller of the two wins.
        assert_eq!(compact_card_rows(12, 3, 40), 12);
        assert_eq!(compact_card_rows(12, 29, 40), 29);
        // Neither may push the card past the pane.
        assert_eq!(compact_card_rows(80, 1, 40), 40);
        assert_eq!(compact_card_rows(1, 400, 40), 40);
        // A pane too short for the floor gets the pane, not a card that
        // overflows it.
        assert_eq!(compact_card_rows(1, 1, 3), 3);
        assert_eq!(compact_card_rows(9, 9, 3), 3);
    }

    #[test]
    fn live_content_extent_measures_cursor_travel_not_adjustment_geometry() {
        // A command that has printed nothing yet still occupies its first row.
        assert_eq!(live_content_extent_for(120, 120, 36), 1);
        // Six rows in, the card is six rows tall.
        assert_eq!(live_content_extent_for(120, 125, 36), 6);
        // Output past the grid caps at the grid: the screen is full and the
        // card is a full viewport, however far the ring has since climbed.
        assert_eq!(live_content_extent_for(120, 155, 36), 36);
        assert_eq!(live_content_extent_for(120, 199_999, 36), 36);
        // The measurement this replaced could not survive a live grid whose
        // adjustment stops tracking the cursor. Measured during
        // `seq 1 200000` on a 36-row grid: adjustment pinned at upper = 5000,
        // cursor at ring row 196_103. Travel is unaffected by either number.
        assert_eq!(live_content_extent_for(2, 196_103, 36), 36);
        // A full-screen repaint homes the cursor above the origin. One row,
        // never a negative one — the caller's high-water holds the card.
        assert_eq!(live_content_extent_for(500, 12, 36), 1);
        // Degenerate grids never produce a card that hides output.
        assert_eq!(live_content_extent_for(0, 0, 0), 1);
        assert_eq!(live_content_extent_for(i64::MIN, i64::MAX, 36), 36);
    }

    #[test]
    fn content_free_activity_notifies_every_observer_synchronously() {
        let callbacks = Rc::new(RefCell::new(Vec::<Box<dyn Fn()>>::new()));
        let seen = Rc::new(RefCell::new(Vec::new()));
        for label in ["tab", "organism"] {
            let seen = seen.clone();
            callbacks
                .borrow_mut()
                .push(Box::new(move || seen.borrow_mut().push(label)));
        }

        emit_activity(&callbacks);
        assert_eq!(seen.borrow().as_slice(), &["tab", "organism"]);
    }

    #[test]
