    #[test]
    fn authoritative_block_start_notifies_every_observer_once() {
        let callbacks = Rc::new(RefCell::new(Vec::<Box<dyn Fn(CommandStartedEvent)>>::new()));
        let seen = Rc::new(RefCell::new(Vec::new()));
        for label in ["first", "second"] {
            let seen = seen.clone();
            callbacks.borrow_mut().push(Box::new(move |event| {
                seen.borrow_mut().push((label, event));
            }));
        }

        let event = CommandStartedEvent {
            command: "cargo test".to_string(),
            cwd: Some("/work/forge".to_string()),
        };
        emit_command_started(&callbacks, event.clone());
        assert_eq!(
            seen.borrow().as_slice(),
            &[("first", event.clone()), ("second", event)]
        );
    }

    #[test]
    fn authoritative_finish_events_drive_the_no_llm_reducer_once_each() {
        use jterm_core::organism::{classify_command, Behavior, NativeOrganism};

        let callbacks = Rc::new(RefCell::new(Vec::<Box<dyn Fn(CommandFinishedEvent)>>::new()));
        let organism = Rc::new(RefCell::new(NativeOrganism::default()));
        let seen = Rc::new(RefCell::new(Vec::new()));
        {
            let organism = organism.clone();
            let seen = seen.clone();
            callbacks.borrow_mut().push(Box::new(move |event| {
                let reaction = organism.borrow_mut().command_finished(
                    classify_command(&event.command),
                    event.exit_code,
                    event.duration_ms,
                );
                seen.borrow_mut().push(reaction.behavior);
            }));
        }

        let emit = |command: &str, exit_code| {
            emit_command_finished(
                &callbacks,
                CommandFinishedEvent {
                    command: command.to_string(),
                    cwd: Some("/work/forge".to_string()),
                    exit_code,
                    duration_ms: Some(250),
                    completion_provenance: super::CompletionProvenance::ShellReported,
                    lifecycle_health: super::BlockLifecycleHealth::Healthy,
                },
            );
        };
        emit("cargo test", Some(101));
        emit("cargo test", Some(101));
        emit("cargo test", Some(0));
        emit("git push", Some(0));
        emit("cargo check", None);

        assert_eq!(
            seen.borrow().as_slice(),
            &[
                Behavior::InspectError,
                Behavior::SitNearError,
                Behavior::Celebrate,
                Behavior::RestAfterPush,
                Behavior::UnknownOutcome,
            ]
        );
    }

    #[test]
    fn prompt_boundary_recovers_missing_d_only_after_shell_regains_foreground() {
        use crate::pty::PtyForeground;

        for state in [BlockState::CollectingOutput, BlockState::AltScreen] {
            assert!(super::prompt_boundary_infers_command_end(
                state,
                PtyForeground::Shell
            ));
            assert!(!super::prompt_boundary_infers_command_end(
                state,
                PtyForeground::Other
            ));
            assert!(!super::prompt_boundary_infers_command_end(
                state,
                PtyForeground::Unknown
            ));
        }
        assert!(!super::prompt_boundary_infers_command_end(
            BlockState::AwaitingCommand,
            PtyForeground::Shell
        ));
    }

    /// Handing the viewport to a TUI hides every card. A selection made before
    /// that must not survive: block-only keys reaching the pane would act on an
    /// active edge nobody can see, and Delete would destroy a card's recorded
    /// output with no visible target.
    /// While a command runs, this label is the only status the pane offers:
    /// what is running and for how long. It used to appear only once the user
    /// had scrolled away from the bottom, so the common case — waiting at the
    /// prompt for a slow build — had no elapsed time and no Stop button at all.
    #[test]
    fn the_running_header_says_what_is_running_and_for_how_long() {
        assert_eq!(
            super::running_header_label("cargo build", 0),
            "▶  cargo build    0s"
        );
        assert_eq!(
            super::running_header_label("cargo build", 59),
            "▶  cargo build    59s"
        );
        assert_eq!(
            super::running_header_label("cargo build", 60),
            "▶  cargo build    1m00s"
        );
        assert_eq!(
            super::running_header_label("cargo build", 3599),
            "▶  cargo build    59m59s"
        );
        assert_eq!(
            super::running_header_label("cargo build", 3600),
            "▶  cargo build    1h00m"
        );
        assert_eq!(
            super::running_header_label("cargo build", 7_384),
            "▶  cargo build    2h03m"
        );

        // A command the pane never captured still reports its elapsed time.
        assert_eq!(
            super::running_header_label("   ", 12),
            "▶  (running)    12s"
        );

        // Raw captured input, rendered safely rather than verbatim.
        let spoofed = super::running_header_label("echo \u{202e}gnp", 1);
        assert!(
            !spoofed.contains('\u{202e}'),
            "a bidi override must not reach the label: {spoofed}"
        );
    }

    /// A click into history — the documented drag-select-to-copy gesture —
    /// strands keyboard focus on a card, and from there every Block-only key
    /// used to do nothing: the whole key surface was mounted on the live VTE
    /// alone. The handler is mounted twice now; these pin the two predicates
    /// that decide when the second mount may answer.
    #[test]
    #[ignore = "requires DISPLAY"]
    fn a_stranded_focus_mount_declines_only_what_the_focused_widget_owns() {
        use gtk4::gdk::{Key, ModifierType};
        use gtk4::prelude::*;

        gtk4::init().expect("gtk init");

        // A card's snapshot VTE is click-focusable and owns no keys, so the
        // root mount answers for it. This is the case the whole mount exists
        // for.
        let card_vte: gtk4::Widget = vte4::Terminal::new().upcast();
        for key in [Key::Up, Key::Down, Key::Delete, Key::Escape, Key::Return] {
            assert!(
                !super::focused_widget_keeps_key(&card_vte, key, ModifierType::empty(), true),
                "{key:?} must reach the block handler from a focused card"
            );
        }

        // The card's own filter entry keeps every key, including the ones the
        // block handler would otherwise claim.
        let entry: gtk4::Widget = gtk4::SearchEntry::new().upcast();
        for key in [Key::Up, Key::Delete, Key::Escape, Key::Return, Key::a] {
            assert!(
                super::focused_widget_keeps_key(&entry, key, ModifierType::empty(), true),
                "a text entry must keep {key:?}"
            );
        }

        // A focused button keeps ordinary GTK activation even when its card is
        // selected. Ctrl+Enter remains Block's explicit modified chord.
        let button: gtk4::Widget = gtk4::Button::new().upcast();
        assert!(super::focused_widget_keeps_key(
            &button,
            Key::Return,
            ModifierType::empty(),
            false,
        ));
        assert!(super::focused_widget_keeps_key(
            &button,
            Key::Return,
            ModifierType::empty(),
            true,
        ));
        assert!(!super::focused_widget_keeps_key(
            &button,
            Key::Return,
            ModifierType::CONTROL_MASK,
            true,
        ));
        assert!(super::focused_widget_keeps_key(
            &button,
            Key::space,
            ModifierType::empty(),
            true,
        ));
        assert!(!super::focused_widget_keeps_key(
            &button,
            Key::Up,
            ModifierType::empty(),
            true,
        ));
    }

    /// The refocus controller runs before the block handler and admits Enter,
    /// Delete and Escape — the three actions a visible selection hint
    /// promises. With a selection on screen those keys belong to the
    /// selection; without one, handing focus back is still the right meaning.
    #[test]
    fn a_visible_selection_owns_the_keys_its_hint_advertises() {
        use gtk4::gdk::{Key, ModifierType};

        for key in [
            Key::Return,
            Key::KP_Enter,
            Key::ISO_Enter,
            Key::Delete,
            Key::Escape,
        ] {
            assert!(
                super::selection_owns_key(true, key),
                "{key:?} is on the selection hint and must reach the selection"
            );
            assert!(
                !super::selection_owns_key(false, key),
                "with no selection {key:?} keeps its refocus meaning"
            );
            // Each one really is a key the refocus controller would otherwise
            // consume; that overlap is why this predicate exists.
            assert!(super::stranded_focus_key_recovers(
                key,
                ModifierType::empty()
            ));
        }

        // Navigation keys are already declined by the refocus controller, so
        // they need no exception here.
        for key in [Key::Up, Key::Down, Key::Page_Up, Key::Home, Key::End] {
            assert!(!super::selection_owns_key(true, key));
            assert!(!super::stranded_focus_key_recovers(
                key,
                ModifierType::empty()
            ));
        }
    }

    #[test]
    fn the_failed_block_section_only_marks_reported_failures() {
        assert!(super::failed_block_section_visible("false", Some(1)));
        assert!(super::failed_block_section_visible("cargo test", Some(101)));
        // Success and unknown status are never reclassified as failures, and
        // background output (blank command) trumps even a non-zero exit.
        assert!(!super::failed_block_section_visible("cargo test", Some(0)));
        assert!(!super::failed_block_section_visible("cargo test", None));
        assert!(!super::failed_block_section_visible("", Some(1)));
        assert!(!super::failed_block_section_visible("   ", Some(1)));
    }

    #[test]
    fn retry_cwd_verification_requires_an_independent_process_match() {
        // frost's verified_local_command_cwd pins, verbatim.
        assert!(super::verified_local_command_cwd(
            "/work/app",
            Some("/work/app"),
            Some("/work/app")
        ));
        assert!(super::verified_local_command_cwd(
            "/work/app",
            None,
            Some("/work/app")
        ));
        assert!(!super::verified_local_command_cwd(
            "/work/app",
            Some("/elsewhere"),
            Some("/work/app")
        ));
        assert!(!super::verified_local_command_cwd("/work/app", None, None));
        assert!(!super::verified_local_command_cwd(
            "/work/app",
            Some("/work/app"),
            Some("/elsewhere")
        ));
        // A relative recorded cwd can never authorize execution.
        assert!(!super::verified_local_command_cwd(
            "work/app",
            Some("work/app"),
            Some("work/app")
        ));
    }

    #[test]
    fn the_failed_block_retry_reason_ladders_every_guard() {
        let eligible = super::failed_block_retry_disabled_reason(
            false,
            "cargo test",
            true,
            false,
            Some("/work/app"),
            Some("/work/app"),
            Some("/work/app"),
        );
        assert_eq!(eligible, None);
        assert_eq!(
            super::failed_block_retry_disabled_reason(
                true,
                "cargo test",
                true,
                false,
                Some("/work/app"),
                Some("/work/app"),
                Some("/work/app"),
            ),
            Some("Select a single block to run it again")
        );
        assert_eq!(
            super::failed_block_retry_disabled_reason(
                false,
                "cargo test",
                true,
                true,
                Some("/work/app"),
                Some("/work/app"),
                Some("/work/app"),
            ),
            Some("The recorded command was shortened and cannot be re-run")
        );
        assert_eq!(
            super::failed_block_retry_disabled_reason(
                false,
                "cargo test",
                false,
                false,
                Some("/work/app"),
                Some("/work/app"),
                Some("/work/app"),
            ),
            Some("The shell did not provide exact command metadata")
        );
        assert_eq!(
            super::failed_block_retry_disabled_reason(
                false,
                "printf one\nprintf two",
                true,
                false,
                Some("/work/app"),
                Some("/work/app"),
                Some("/work/app"),
            ),
            Some("The recorded command cannot be re-run exactly")
        );
        assert_eq!(
            super::failed_block_retry_disabled_reason(
                false,
                "cargo test",
                true,
                false,
                None,
                Some("/work/app"),
                Some("/work/app"),
            ),
            Some("The command working directory is unavailable")
        );
        // The cwd legs refuse a moved shell, an unobservable process cwd
        // (SSH/tmux wrapper), and a conflicting OSC report alike.
        assert_eq!(
            super::failed_block_retry_disabled_reason(
                false,
                "cargo test",
                true,
                false,
                Some("/work/app"),
                Some("/elsewhere"),
                Some("/work/app"),
            ),
            Some("The shell's current directory differs from the command's recorded directory")
        );
        assert_eq!(
            super::failed_block_retry_disabled_reason(
                false,
                "cargo test",
                true,
                false,
                Some("/work/app"),
                None,
                None,
            ),
            Some("The shell's current directory differs from the command's recorded directory")
        );
    }

    #[test]
    fn the_selection_hint_only_names_actions_available_for_that_selection() {
        assert_eq!(
            super::finished_selection_hint(1, true, true),
            super::SELECTION_HINT_RUN
        );
        assert_eq!(
            super::finished_selection_hint(2, true, true),
            "Esc cancel  ·  2 selected  ·  ↵ recall all",
            "multi-selection names its extent and insert-all action"
        );
        assert_eq!(
            super::finished_selection_hint(1, true, false),
            super::SELECTION_HINT_RECALL,
            "a multiline or sanitized command remains recall-only"
        );
        assert_eq!(
            super::finished_selection_hint(1, false, false),
            super::SELECTION_HINT_REMOVE,
            "a background-only selection only advertises cancellation"
        );
        assert_eq!(
            super::finished_selection_hint(3, false, false),
            "Esc cancel  ·  3 selected",
            "an unavailable batch still makes its selection extent explicit"
        );
        for hint in [
            super::SELECTION_HINT_RUN,
            super::SELECTION_HINT_RECALL,
            super::SELECTION_HINT_REMOVE,
        ] {
            assert!(hint.starts_with("Esc cancel"));
            assert!(!hint.contains("Prompt ready"));
            assert!(
                !hint.contains("Del"),
                "the compact hint must not advertise destructive deletion"
            );
        }
    }

    #[test]
    fn a_refused_selection_action_names_the_gate_and_the_non_action() {
        use super::{CommandPromptStatus, SelectionAction, SelectionActionRefusal};

        assert_eq!(
            super::selection_refusal_hint(
                SelectionAction::Run,
                SelectionActionRefusal::Prompt(CommandPromptStatus::HasInput),
            ),
            "Esc cancel  ·  Prompt has input  ·  nothing run"
        );
        assert_eq!(
            super::selection_refusal_hint(
                SelectionAction::Recall,
                SelectionActionRefusal::Prompt(CommandPromptStatus::Running),
            ),
            "Esc cancel  ·  Command running  ·  nothing recalled"
        );
        assert_eq!(
            super::selection_refusal_hint(
                SelectionAction::Recall,
                SelectionActionRefusal::UnsafeRecall,
            ),
            "Esc cancel  ·  Selection cannot be recalled safely  ·  nothing recalled"
        );
    }

    #[test]
    #[ignore = "requires DISPLAY"]
    fn a_refusal_flash_is_visible_exposed_and_restores_only_the_latest_status() {
        use gtk4::prelude::*;

        gtk4::init().expect("gtk init");
        let config = crate::config::Config::safe_defaults();
        let card = super::FinishedBlock::new(
            91,
            "$ ",
            "cargo test",
            None,
            "ok\r\n",
            Some(0),
            &config,
            Some(5),
            Some(1_700_000_000_000),
            None,
            80,
        );
        let selected = Rc::new(RefCell::new(HashSet::from([91])));
        let active = Rc::new(Cell::new(Some(91)));
        super::sync_finished_block_selection(std::slice::from_ref(&card), &selected, &active);
        let message = "Esc cancel  ·  Prompt has input  ·  nothing run".to_string();

        super::flash_finished_selection_refusal_for(
            std::slice::from_ref(&card),
            Some(91),
            message.clone(),
            std::time::Duration::from_millis(30),
        );

        assert_eq!(card.selection_hint.text().as_str(), message);
        assert_eq!(
            card.selection_hint.tooltip_text().as_deref(),
            Some(message.as_str())
        );
        assert_eq!(
            card.selection_hint.accessible_role(),
            gtk4::AccessibleRole::Status
        );

        let run_for = |millis| {
            let loop_ = gtk4::glib::MainLoop::new(None, false);
            let quit = loop_.clone();
            gtk4::glib::timeout_add_local_once(
                std::time::Duration::from_millis(millis),
                move || quit.quit(),
            );
            loop_.run();
        };

        // Repeating the same refusal refreshes its full lifetime. The old
        // timeout must not restore the steady legend underneath the new one.
        run_for(10);
        super::flash_finished_selection_refusal_for(
            std::slice::from_ref(&card),
            Some(91),
            message.clone(),
            std::time::Duration::from_millis(70),
        );
        run_for(30);
        assert_eq!(card.selection_hint.text().as_str(), message);

        // A different, newer refusal owns the eventual restoration too. The
        // second timeout used to restore the first transient message forever.
        let newer = "Esc cancel  ·  Command running  ·  nothing recalled".to_string();
        super::flash_finished_selection_refusal_for(
            std::slice::from_ref(&card),
            Some(91),
            newer.clone(),
            std::time::Duration::from_millis(70),
        );
        run_for(40);
        assert_eq!(card.selection_hint.text().as_str(), newer);
        run_for(40);
        assert_eq!(
            card.selection_hint.text().as_str(),
            super::SELECTION_HINT_RUN
        );
        assert_eq!(card.selection_hint.tooltip_text(), None);
    }

    /// Deleted cards go back where their ids say they belong. Document order is
    /// id order, so a card removed from the middle returns to the middle even
    /// if newer commands ran in the meantime — the Clear path's prepend would
    /// have put it at the top.
    #[test]
    fn a_restored_block_lands_where_its_id_belongs() {
        // Live document ids, ascending, as the pane always holds them.
        let live = [10_u64, 20, 30];

        assert_eq!(super::restore_position_by_id(live, 5), 0, "older than all");
        assert_eq!(super::restore_position_by_id(live, 15), 1);
        assert_eq!(super::restore_position_by_id(live, 25), 2);
        assert_eq!(
            super::restore_position_by_id(live, 40),
            3,
            "newer than all: appended after the last card"
        );

        // An empty pane takes everything at the front, which is what makes the
        // Clear generation's prepend and this one agree.
        assert_eq!(super::restore_position_by_id([], 7), 0);

        // Restoring several in ascending order keeps their relative order.
        let mut document: Vec<u64> = live.to_vec();
        for id in [15_u64, 16, 25] {
            let position = super::restore_position_by_id(document.iter().copied(), id);
            document.insert(position, id);
        }
        assert_eq!(document, vec![10, 15, 16, 20, 25, 30]);
    }

    /// With a filter on, Up/Down must walk the cards the pane is showing. Raw
    /// index arithmetic would step onto hidden ones and give the keyboard an
    /// active edge nobody can see.
    #[test]
    fn selection_steps_over_the_cards_a_filter_hid() {
        // Cards 0..6 with 1, 3 and 4 hidden by a filter.
        let shown = [0_usize, 2, 5, 6];

        // Entering from nothing, going up, lands on the newest SHOWN card.
        assert_eq!(super::step_selectable(&shown, None, -1), Some(6));
        // Going down with nothing selected refuses, as it always has.
        assert_eq!(super::step_selectable(&shown, None, 1), None);

        // Stepping skips the hidden run rather than landing in it.
        assert_eq!(super::step_selectable(&shown, Some(5), -1), Some(2));
        assert_eq!(super::step_selectable(&shown, Some(2), -1), Some(0));
        assert_eq!(super::step_selectable(&shown, Some(2), 1), Some(5));

        // The ends hold: up at the oldest stays, down at the newest stops.
        assert_eq!(super::step_selectable(&shown, Some(0), -1), Some(0));
        assert_eq!(super::step_selectable(&shown, Some(6), 1), None);

        // A current position that is itself hidden is not on the walk, so it
        // behaves like entering fresh.
        assert_eq!(super::step_selectable(&shown, Some(3), -1), Some(6));

        // Nothing shown: nothing to step to, in either direction.
        assert_eq!(super::step_selectable(&[], None, -1), None);
        assert_eq!(super::step_selectable(&[], Some(0), 1), None);
    }

    /// Folding has to shrink the card's recorded height as well as hide its
    /// widget. The virtualization canvas is measured from `estimated_height`,
    /// so a bulk collapse that only hid widgets would leave the document the
    /// same size and the scrollbar describing space nothing occupies.
    #[test]
    fn a_folded_card_stops_claiming_its_outputs_height() {
        let config = crate::config::Config::safe_defaults();
        let mut data = super::BlockData {
            id: 1,
            prompt: "$ ".to_string(),
            cmd: "seq 1 200".to_string(),
            cmd_markup: None,
            output: (1..=200).map(|i| format!("line {i}\n")).collect(),
            exit_code: Some(0),
            lifecycle_schema: crate::block_view::blocks::BLOCK_LIFECYCLE_SCHEMA,
            completion_provenance: super::CompletionProvenance::ShellReported.into(),
            start_mark_seen: true,
            line_count: 200,
            estimated_height: 0,
            start_time_ms: None,
            end_time_ms: None,
            duration_ms: Some(5),
            cwd: None,
            cols: 80,
            command_exact: false,
            command_truncated: false,
        };

        let expanded = super::collapsed_aware_block_height(&config, &data, false, 80);
        let folded = super::collapsed_aware_block_height(&config, &data, true, 80);
        assert!(
            folded < expanded,
            "folded {folded} must be shorter than expanded {expanded}"
        );

        // Unfolding restores exactly the height the card had, so a
        // collapse/expand round trip leaves the canvas where it started.
        data.estimated_height = folded;
        assert_eq!(
            super::collapsed_aware_block_height(&config, &data, false, 80),
            expanded
        );

        // A command with no output is already header-and-command tall, so
        // folding it changes nothing.
        data.output = String::new();
        assert_eq!(
            super::collapsed_aware_block_height(&config, &data, true, 80),
            super::collapsed_aware_block_height(&config, &data, false, 80),
        );
    }

    fn idle_guards() -> super::PromptSubmitGuards {
        super::PromptSubmitGuards {
            state: BlockState::AwaitingCommand,
            pty_synced: false,
            submission_pending: false,
            pending_typeahead: false,
            fidelity: TypedShadowFidelity::Inexact,
        }
    }

    #[test]
    fn a_safe_rerun_is_admitted_with_or_without_bracketed_paste() {
        for bracketed_paste in [true, false] {
            assert!(super::rerun_is_admissible(
                idle_guards(),
                "cargo test",
                bracketed_paste
            ));
        }
    }

    /// Every refusal an execution has that an insertion does not.
    #[test]
    fn a_rerun_refuses_anything_it_could_execute_wrongly() {
        // A prompt that is not idle: the bytes would reach a running program.
        for state in [
            BlockState::CollectingOutput,
            BlockState::AltScreen,
            BlockState::PostCommand,
            BlockState::RawFallback,
            BlockState::Idle,
        ] {
            let guards = super::PromptSubmitGuards {
                state,
                ..idle_guards()
            };
            assert!(
                !super::rerun_is_admissible(guards, "ls", true),
                "{state:?} must not accept a re-run"
            );
        }

        // A prompt the user has already touched, in each of the four ways.
        let dirty = [
            super::PromptSubmitGuards {
                pty_synced: true,
                ..idle_guards()
            },
            super::PromptSubmitGuards {
                submission_pending: true,
                ..idle_guards()
            },
            super::PromptSubmitGuards {
                pending_typeahead: true,
                ..idle_guards()
            },
            super::PromptSubmitGuards {
                fidelity: TypedShadowFidelity::ExactSubmitted,
                ..idle_guards()
            },
        ];
        for guards in dirty {
            assert!(
                !super::rerun_is_admissible(guards, "ls", true),
                "a prompt that is not clean must not accept a re-run"
            );
        }

        // Nothing to run.
        assert!(!super::rerun_is_admissible(idle_guards(), "", true));
        assert!(!super::rerun_is_admissible(idle_guards(), "   \n ", true));

        // A command the encoder must cut to its first line. Insertion may
        // truncate — the user still reads the line — but executing a silently
        // truncated prefix cannot be undone.
        let multiline = "echo one\necho two";
        assert!(
            super::build_command_recall(multiline, false)
                .risk
                .truncated_to_first_line,
            "the fixture must actually be truncated by the encoder"
        );
        assert!(
            !super::rerun_is_admissible(idle_guards(), multiline, false),
            "a truncated command must never be executed"
        );

        // Sanitization is acceptable for insertion because the changed text is
        // visible before Enter. A one-click re-run must remain byte-identical
        // to the history command instead of executing a cleaned-up surprise.
        for rewritten in [
            "echo \x1b[31mred",
            "printf docs\x1b[201~oops",
            "printf trailing-newline\n",
            "printf\0argument",
        ] {
            let paste = super::build_command_recall(rewritten, false);
            assert!(
                paste.risk.had_controls
                    || paste.risk.had_embedded_paste_marker
                    || paste.echo_text != rewritten,
                "fixture must exercise a sanitizer rewrite: {rewritten:?}"
            );
            assert!(
                !super::rerun_is_admissible(idle_guards(), rewritten, false),
                "sanitizer-rewritten history must stay insert-only: {rewritten:?}"
            );
        }
        for placeholder in [
            super::TRUNCATED_COMMAND_PLACEHOLDER,
            super::UNAVAILABLE_COMMAND_PLACEHOLDER,
        ] {
            assert!(
                !super::rerun_is_admissible(idle_guards(), placeholder, false),
                "an internal capture placeholder must never become shell input"
            );
        }
    }

    #[test]
    fn selection_mode_always_consumes_ctrl_enter_even_when_rerun_refuses() {
        assert!(!super::block_selection_owns_ctrl_enter(None, 0));
        assert!(super::block_selection_owns_ctrl_enter(Some(7), 1));
        assert!(
            super::block_selection_owns_ctrl_enter(None, 1),
            "even a transiently inconsistent selection set must fail closed"
        );

        let busy = super::PromptSubmitGuards {
            state: BlockState::CollectingOutput,
            ..idle_guards()
        };
        assert!(!super::rerun_is_admissible(busy, "ls", false));
        assert!(
            super::block_selection_owns_ctrl_enter(Some(7), 1),
            "a refusal while selected must remain Block-owned, never reach VTE"
        );
    }

    #[test]
    fn only_unmodified_enter_owns_history_recall() {
        use gtk4::gdk::Key;
        assert!(super::block_selection_owns_plain_enter(
            Key::Return,
            false,
            false,
            false
        ));
        for (ctrl, shift, alt) in [
            (true, false, false),
            (false, true, false),
            (false, false, true),
            (true, true, false),
        ] {
            assert!(
                !super::block_selection_owns_plain_enter(Key::Return, ctrl, shift, alt),
                "modified Enter must remain available to the focused surface"
            );
        }
    }

    /// A re-run acts on one card the user pointed at. A multi-card selection
    /// stays insert-only, and a background card has no command to run.
    #[test]
    fn only_a_lone_command_card_is_rerunnable() {
        use std::collections::HashSet;

        let ids = HashSet::from([7_u64]);
        assert!(super::lone_rerunnable_selection(&[], &ids, Some(7)).is_none());
        assert!(super::lone_rerunnable_selection(&[], &HashSet::new(), None).is_none());

        // Two selected cards: refused before any card lookup happens.
        let many = HashSet::from([7_u64, 8]);
        assert!(super::lone_rerunnable_selection(&[], &many, Some(8)).is_none());
    }

    #[test]
    #[ignore = "requires DISPLAY"]
    fn entering_alt_screen_ends_the_block_selection_it_hides() {
        use gtk4::prelude::WidgetExt as _;

        gtk4::init().expect("gtk init");
        let config = crate::config::Config::safe_defaults();
        let cards: Vec<super::FinishedBlock> = (1..=2)
            .map(|id| {
                super::FinishedBlock::new(
                    id,
                    "$ ",
                    "echo hi",
                    None,
                    "hi\r\n",
                    Some(0),
                    &config,
                    Some(5),
                    None,
                    None,
                    80,
                )
            })
            .collect();
        let finished = Rc::new(RefCell::new(cards));
        let visible: Rc<RefCell<std::collections::HashSet<usize>>> =
            Rc::new(RefCell::new(std::collections::HashSet::new()));
        let fullscreen = Rc::new(Cell::new(false));
        let ids: super::SelectedBlockIds =
            Rc::new(RefCell::new(std::collections::HashSet::from([1, 2])));
        let active = Rc::new(Cell::new(Some(2)));
        let anchor_id = Rc::new(Cell::new(Some(1)));

        super::enter_fullscreen(
            &finished,
            &visible,
            &fullscreen,
            super::BlockSelectionRefs {
                ids: &ids,
                active: &active,
                anchor: &anchor_id,
            },
        );

        assert!(fullscreen.get());
        assert!(
            finished
                .borrow()
                .iter()
                .all(|card| !card.widget().is_visible()),
            "every card is hidden while the alt-screen app owns the viewport"
        );
        assert!(ids.borrow().is_empty(), "the selection set must be emptied");
        assert_eq!(active.get(), None, "no card may stay the active edge");
        assert_eq!(anchor_id.get(), None, "no card may stay the range anchor");
        for card in finished.borrow().iter() {
            assert!(!card.widget().has_css_class("block-selected"));
            assert!(!card.widget().has_css_class("block-selection-active"));
        }
    }

    #[test]
    fn constructor_propagates_injected_spawn_failure_without_panicking() {
        let config = crate::config::load_safe_config().0;
        let shell_argv = vec!["injected-shell".to_string()];
        let attempt = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            super::TermView::new_with_spawner(
                &config,
                &crate::config::TerminalMode::Block,
                &shell_argv,
                None,
                Some("injected-session"),
                &[],
                |_argv, _cwd, _env, _enable_shell_token| {
                    Err(std::io::Error::new(
                        std::io::ErrorKind::NotFound,
                        "injected PTY spawn failure",
                    ))
                },
            )
        }));

        let construction = match attempt {
            Ok(construction) => construction,
            Err(_) => panic!("TermView construction panicked on a PTY spawn error"),
        };
        let error = match construction {
            Ok(_) => panic!("injected PTY spawn failure unexpectedly constructed a TermView"),
            Err(error) => error,
        };
        assert_eq!(error.kind(), std::io::ErrorKind::NotFound);
        assert_eq!(error.to_string(), "injected PTY spawn failure");
    }

    /// The Unified backend's only durable output. The record must carry the
    /// whole command identity the engine hands to `finalize_block` (nothing
    /// about a zone may need re-deriving later), and the table must stay
    /// bounded — it is the one allocation this mode grows per command.
    #[test]
    fn unified_records_keep_the_command_identity_and_drop_the_oldest_past_the_cap() {
        let record = |id: u64, cmd: &str| CompletedCommandRecord {
            id,
            cmd: cmd.to_string(),
            exit_code: Some(3),
            start_time_ms: None,
            end_time_ms: Some(1_700_000_000_000),
            duration_ms: Some(1200),
            cwd: Some("/tmp/work".to_string()),
            is_background: false,
            completion_provenance: super::CompletionProvenance::ShellReported,
            command_source: super::CommandTextSource::Screen,
            start_mark_seen: true,
        };

        let mut zones = UnifiedZoneStore::new();
        record_unified_zone(&mut zones, record(1, "first"), 2);
        zones.insert_snapshot(
            1,
            ZoneOutputSnapshot {
                plain: "first output".to_string(),
                truncated: false,
            },
        );
        record_unified_zone(&mut zones, record(2, "second"), 2);
        record_unified_zone(&mut zones, record(3, "third"), 2);

        assert_eq!(
            zones.records.iter().map(|zone| zone.id).collect::<Vec<_>>(),
            vec![2, 3],
            "the oldest zone is dropped, newest-last order preserved"
        );
        assert_eq!(
            zones.snapshot(1),
            None,
            "a drained record takes its snapshot with it"
        );
        assert_eq!(zones.snapshot_bytes, 0);
        let newest = zones.records.back().expect("a recorded zone");
        assert_eq!(newest.cmd, "third");
        assert_eq!(newest.exit_code, Some(3));
        assert_eq!(newest.duration_ms, Some(1200));
        assert_eq!(newest.cwd.as_deref(), Some("/tmp/work"));
        assert_eq!(newest.end_time_ms, Some(1_700_000_000_000));

        // A degenerate cap must still bound the table rather than panic.
        record_unified_zone(&mut zones, record(4, "fourth"), 0);
        assert_eq!(zones.records.len(), 1);
        assert_eq!(zones.records[0].id, 4);
    }

    #[test]
    fn unified_bookmarks_follow_record_retention_not_snapshot_eviction() {
        let record = |id: u64| CompletedCommandRecord {
            id,
            cmd: format!("command-{id}"),
            exit_code: Some(0),
            start_time_ms: None,
            end_time_ms: None,
            duration_ms: None,
            cwd: None,
            is_background: false,
            completion_provenance: super::CompletionProvenance::ShellReported,
            command_source: super::CommandTextSource::Screen,
            start_mark_seen: true,
        };
        let mut zones = UnifiedZoneStore::new();
        record_unified_zone(&mut zones, record(1), 2);
        zones.insert_snapshot(
            1,
            ZoneOutputSnapshot {
                plain: "retained output".to_string(),
                truncated: false,
            },
        );
        record_unified_zone(&mut zones, record(2), 2);

        let mut bookmarks = super::BookmarkState::default();
        bookmarks.toggle(1);
        bookmarks.toggle(2);
        let revision_before_snapshot_eviction = bookmarks.revision();
        zones.enforce_snapshot_budget(0);
        assert!(bookmarks.contains(1));
        assert!(bookmarks.contains(2));
        assert_eq!(bookmarks.revision(), revision_before_snapshot_eviction);

        let retired = record_unified_zone(&mut zones, record(3), 2);
        assert_eq!(retired, [1]);
        assert_eq!(super::prune_retired_bookmarks(&mut bookmarks, &retired), 1);
        assert!(!bookmarks.contains(1));
        assert!(bookmarks.contains(2));
        assert_eq!(bookmarks.revision(), revision_before_snapshot_eviction + 1);
    }

    /// The global budget only ever removes snapshot BYTES, oldest record
    /// first; every record survives and later looks up its own snapshot by
    /// id, so eviction can never shift output onto a different command.
    #[test]
    fn snapshot_budget_evicts_oldest_first_and_keeps_ids_aligned() {
        let record = |id: u64| CompletedCommandRecord {
            id,
            cmd: format!("command-{id}"),
            exit_code: Some(0),
            start_time_ms: None,
            end_time_ms: None,
            duration_ms: None,
            cwd: None,
            is_background: false,
            completion_provenance: super::CompletionProvenance::ShellReported,
            command_source: super::CommandTextSource::Screen,
            start_mark_seen: true,
        };
        let mut zones = UnifiedZoneStore::new();
        for id in 1..=3 {
            record_unified_zone(&mut zones, record(id), 10);
            zones.insert_snapshot(
                id,
                ZoneOutputSnapshot {
                    plain: format!("output-{id}-{}", "x".repeat(96)),
                    truncated: false,
                },
            );
        }
        let per_snapshot = zones.snapshot_bytes / 3;

        zones.enforce_snapshot_budget(per_snapshot * 2);
        assert_eq!(zones.records.len(), 3, "records are never removed");
        assert_eq!(zones.snapshot(1), None, "the oldest snapshot goes first");
        assert!(zones.snapshot(2).is_some());
        assert!(zones.snapshot(3).is_some());
        assert_eq!(zones.snapshot_bytes, per_snapshot * 2);
        assert!(zones
            .snapshot(3)
            .is_some_and(|snapshot| snapshot.plain.starts_with("output-3-")));

        zones.enforce_snapshot_budget(0);
        assert_eq!(zones.snapshot_bytes, 0);
        assert!((1..=3).all(|id| zones.snapshot(id).is_none()));
        assert_eq!(zones.records.len(), 3);
    }

    #[test]
    fn zone_snapshot_takes_the_bounded_tail_and_reports_truncation() {
        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ring.append(b"head head head\r\ntail line\r\n");
        let snapshot = zone_output_snapshot_from_ring(&mut ring, 11).expect("tail snapshot");
        assert_eq!(snapshot.plain, "tail line");
        assert!(snapshot.truncated);

        let complete = zone_output_snapshot_from_ring(&mut ring, 4096).expect("full snapshot");
        assert_eq!(complete.plain, "head head head\ntail line");
        assert!(!complete.truncated);
    }

    /// A byte-bounded tail cut can land inside an escape sequence; its
    /// introducer lies before the cut, so the stripper would otherwise emit
    /// the parameter bytes as literal text.
    #[test]
    fn zone_snapshot_tail_swallows_a_leading_partial_escape_sequence() {
        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ring.append(b"before\r\n\x1b[38;5;196mred tail\x1b[0m\r\n");
        // The cut lands between `\x1b[38;` and `5;196m`: the retained bytes
        // start mid-parameters.
        let max_bytes = b"5;196mred tail\x1b[0m\r\n".len();
        let snapshot = zone_output_snapshot_from_ring(&mut ring, max_bytes).expect("tail snapshot");
        assert_eq!(snapshot.plain, "red tail");
        assert!(snapshot.truncated);

        // A cut inside a multi-byte scalar resumes at the next boundary.
        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ring.append("padding界tail".as_bytes());
        let snapshot =
            zone_output_snapshot_from_ring(&mut ring, "界tail".len() - 1).expect("tail snapshot");
        assert_eq!(snapshot.plain, "tail");
        assert!(snapshot.truncated);
    }

    /// An escape sequence can be longer than the whole tail bound, and its
    /// terminator can be the last captured byte or absent altogether. Skipping
    /// it must never consume the buffer: an empty snapshot is stored as no
    /// snapshot at all, which reads exactly like a command that printed
    /// nothing and carries no truncation signal either.
    #[test]
    fn zone_snapshot_tail_survives_an_escape_sequence_longer_than_the_bound() {
        let max_bytes = 4096;

        // OSC 52 clipboard write terminated by the final captured byte.
        let terminated = format!(
            "200 KB of log\r\n\x1b]52;c;{}\x07",
            "QUJD".repeat(max_bytes)
        );
        // The tail helper's own invariant, whoever calls it: a non-empty
        // capture never yields an empty tail.
        let (tail, cut) = super::bounded_output_tail(terminated.as_bytes(), max_bytes);
        assert!(cut);
        assert!(!tail.is_empty(), "the escape skip must not eat the buffer");

        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ring.append(terminated.as_bytes());
        let snapshot = zone_output_snapshot_from_ring(&mut ring, max_bytes).expect("tail snapshot");
        assert!(snapshot.plain.contains("QUJD"));
        assert!(snapshot.truncated);

        // The same payload with no terminator at all.
        let unterminated = format!("200 KB of log\r\n\x1b]52;c;{}", "QUJD".repeat(max_bytes));
        let (tail, cut) = super::bounded_output_tail(unterminated.as_bytes(), max_bytes);
        assert!(cut);
        assert!(!tail.is_empty(), "the escape skip must not eat the buffer");

        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ring.append(unterminated.as_bytes());
        let snapshot = zone_output_snapshot_from_ring(&mut ring, max_bytes).expect("tail snapshot");
        assert!(snapshot.plain.contains("QUJD"));
        assert!(snapshot.truncated);

        // A skip that lands inside the buffer but leaves nothing visible falls
        // back to the unadjusted cut: stray parameter characters still report
        // that this command produced output.
        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ring.append(b"xxxxxxxx\x1b]0;title\x07\n");
        let snapshot =
            zone_output_snapshot_from_ring(&mut ring, "title\x07\n".len()).expect("tail snapshot");
        assert!(snapshot.plain.starts_with("title"));
        assert!(snapshot.truncated);
    }

    /// `strip_ansi` is a replay, not a filter: one line past the replay grid's
    /// column bound stops it, and every later byte — the command's verdict
    /// lines included — is discarded. Nothing in the retained text says so, so
    /// both snapshot constructors have to say it.
    #[test]
    fn zone_snapshot_reports_an_aborted_ansi_replay_as_truncated() {
        // Colour leaves the no-control fast path, so the replay actually runs.
        let raw = format!(
            "\x1b[32mbuilding\x1b[0m\r\n{}\r\nERROR: build failed\r\n",
            "w".repeat(20_000)
        );

        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ring.append(raw.as_bytes());
        let snapshot = zone_output_snapshot_from_ring(&mut ring, MAX_ZONE_SNAPSHOT_BYTES)
            .expect("captured output");
        assert!(
            !snapshot.plain.contains("ERROR: build failed"),
            "the replay stopped at the column bound"
        );
        assert!(snapshot.truncated);

        // The same loss through the memoized-plain path, where the journal
        // materialized the text before finalize could read the ring.
        let output = Rc::new(RefCell::new(BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES)));
        output.borrow_mut().append(raw.as_bytes());
        let payload = super::LazyBlockRenderPayload::new(
            String::new(),
            super::CapturedFinalizeOutput::Foreground(output),
        );
        payload.materialize();
        let snapshot = payload
            .output_snapshot(MAX_ZONE_SNAPSHOT_BYTES)
            .expect("memoized output");
        assert!(!snapshot.plain.contains("ERROR: build failed"));
        assert!(snapshot.truncated);
    }

    /// The per-zone cap and the retention budget must bound the same
    /// quantity. The replay pads each row out to the cursor, so a raw tail far
    /// inside the cap can still strip to many times it — and it is the
    /// stripped text that `insert_snapshot` charges and eviction acts on.
    #[test]
    fn zone_snapshot_bounds_the_stripped_text_the_budget_charges() {
        let mut ring = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        let raw = "\x1b[999C.\n".repeat(100);
        assert!(raw.len() < MAX_ZONE_SNAPSHOT_BYTES);
        ring.append(raw.as_bytes());

        let snapshot = zone_output_snapshot_from_ring(&mut ring, MAX_ZONE_SNAPSHOT_BYTES)
            .expect("captured output");
        assert!(
            snapshot.plain.len() <= MAX_ZONE_SNAPSHOT_BYTES,
            "sparse cursor writes expanded past the per-zone cap: {}",
            snapshot.plain.len()
        );
        assert!(snapshot.truncated);
    }

    #[test]
    fn zone_snapshot_reports_a_wrapped_ring_as_truncated() {
        let mut ring = BoundedByteRing::new(8);
        ring.append(b"0123456789");
        let snapshot =
            zone_output_snapshot_from_ring(&mut ring, MAX_ZONE_SNAPSHOT_BYTES).expect("snapshot");
        assert_eq!(snapshot.plain, "23456789");
        assert!(
            snapshot.truncated,
            "front bytes the ring already dropped are truncation even under the tail bound"
        );
    }

    #[test]
    fn zone_snapshot_never_fabricates_an_empty_string() {
        let mut empty = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        assert_eq!(
            zone_output_snapshot_from_ring(&mut empty, MAX_ZONE_SNAPSHOT_BYTES),
            None
        );

        let mut ansi_only = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        ansi_only.append(b"\x1b[2K\r");
        assert_eq!(
            zone_output_snapshot_from_ring(&mut ansi_only, MAX_ZONE_SNAPSHOT_BYTES),
            None
        );

        assert_eq!(
            zone_output_snapshot_from_plain("   \n", MAX_ZONE_SNAPSHOT_BYTES, false),
            None
        );
        let materialized = zone_output_snapshot_from_plain("plain output", 5, false).expect("tail");
        assert_eq!(materialized.plain, "utput");
        assert!(materialized.truncated);
    }

    /// The char-boundary guard on the memoized-plain path: the byte cut can
    /// land inside a scalar there exactly as it can in the raw ring, and
    /// indexing a `str` at a non-boundary panics — on the GTK main thread, at
    /// finalize, for any command whose tail is not ASCII.
    #[test]
    fn zone_snapshot_from_plain_cuts_on_a_char_boundary() {
        let snapshot = zone_output_snapshot_from_plain("padding界tail", "界tail".len() - 1, false)
            .expect("tail snapshot");
        assert_eq!(snapshot.plain, "tail");
        assert!(snapshot.truncated);
    }

    /// Whatever the ring dropped out of its front is invisible in the decoded
    /// text, and under jsh the journal materializes that text before finalize
    /// reads the ring — so the marker has to be carried, not re-derived.
    #[test]
    fn materialized_payload_still_reports_a_wrapped_ring_as_truncated() {
        let output = Rc::new(RefCell::new(BoundedByteRing::new(8)));
        output.borrow_mut().append(b"0123456789");
        let payload = super::LazyBlockRenderPayload::new(
            String::new(),
            super::CapturedFinalizeOutput::Foreground(output),
        );

        // The journal observer runs first and consumes the ring.
        payload.materialize();
        let snapshot = payload
            .output_snapshot(MAX_ZONE_SNAPSHOT_BYTES)
            .expect("memoized output");
        assert_eq!(snapshot.plain, "23456789");
        assert!(
            snapshot.truncated,
            "the ring's wrap marker survives materialization"
        );
    }

    #[test]
    fn unified_search_extracts_viewport_before_huge_old_history() {
        let mut requested_rows = Vec::new();
        let captured = capture_vte_search_windows_bounded(
            -100_000,
            4,
            0,
            80,
            400,
            || false,
            |span| {
                requested_rows.push(span.start_row);
                Some(String::new())
            },
        );

        assert_eq!(requested_rows[..4], [0, 1, 2, 3]);
        assert_eq!(requested_rows[4], -100_000);
        assert!(!captured.viewport_to_tail.incomplete);
        assert_eq!(captured.viewport_to_tail.work_cells, 320);
        let history = captured.oldest_history.expect("remaining bounded history");
        assert!(history.incomplete);
        assert_eq!(history.work_cells, 80);
        assert_eq!(
            captured.viewport_to_tail.work_cells + history.work_cells,
            400,
            "both windows share one hard extraction budget"
        );
    }

    #[test]
    fn unified_search_capture_bounds_native_requests_and_retained_text() {
        let budget = 73usize;
        let mut requested_cells = 0usize;
        let mut requested_spans = Vec::new();
        let captured = capture_vte_rows_bounded(
            -10_000,
            10_000,
            80,
            budget,
            || false,
            |span| {
                requested_cells = requested_cells.saturating_add(span.work_cells);
                requested_spans.push(span);
                // Model a native extractor whose UTF-8 result expands well
                // beyond its grid-cell request. Retention still must not cross
                // the byte ceiling.
                Some("雪".repeat(span.work_cells))
            },
        );

        assert!(captured.incomplete);
        assert!(captured.text.len() <= budget);
        assert!(requested_cells <= budget);
        assert!(!requested_spans.is_empty());
        assert!(requested_spans
            .iter()
            .all(|span| span.start_row == span.end_row));
        assert!(requested_spans
            .iter()
            .all(|span| usize::try_from(span.end_col).ok() == Some(span.work_cells)));
        assert!(
            requested_spans.len() < 20_001,
            "the whole ring was not requested"
        );

        let mut calls = 0usize;
        let timed_out = capture_vte_rows_bounded(
            0,
            999,
            80,
            4 * 1024 * 1024,
            || true,
            |_| {
                calls += 1;
                Some(String::new())
            },
        );
        assert!(timed_out.incomplete);
        assert!(timed_out.text.is_empty());
        assert_eq!(calls, 0, "the time guard fires before another VTE call");
    }

    #[test]
    fn unified_search_capture_charges_every_single_row_half_open_range() {
        let mut spans = Vec::new();
        let captured = capture_vte_rows_bounded(
            5,
            99,
            10,
            25,
            || false,
            |span| {
                spans.push(span);
                Some(String::new())
            },
        );
        assert_eq!(
            spans,
            vec![
                super::VteCaptureSpan {
                    start_row: 5,
                    end_row: 5,
                    end_col: 10,
                    work_cells: 10,
                },
                super::VteCaptureSpan {
                    start_row: 6,
                    end_row: 6,
                    end_col: 10,
                    work_cells: 10,
                },
                super::VteCaptureSpan {
                    start_row: 7,
                    end_row: 7,
                    end_col: 5,
                    work_cells: 5,
                },
            ]
        );
        assert_eq!(spans.iter().map(|span| span.work_cells).sum::<usize>(), 25);
        assert!(captured.incomplete);

        let mut exact_spans = Vec::new();
        let exact = capture_vte_rows_bounded(
            0,
            2,
            4,
            12,
            || false,
            |span| {
                exact_spans.push(span);
                Some(String::new())
            },
        );
        assert!(!exact.incomplete);
        assert_eq!(exact_spans.len(), 3);
        assert!(exact_spans.iter().all(|span| {
            span.start_row == span.end_row && span.end_col == 4 && span.work_cells == 4
        }));
        assert_eq!(
            exact_spans
                .iter()
                .map(|span| span.work_cells)
                .sum::<usize>(),
            12
        );
    }

    /// A card may be built under the old density and mounted only after this
    /// pane switched to compact. Both the scrolling block-list boundary and
    /// the dock/direct-integration boundary must reconcile it at ownership
    /// admission time.
    #[test]
    #[ignore = "requires DISPLAY"]
    fn late_inline_notice_adopts_the_panes_current_density() {
        use gtk4::prelude::*;

        gtk4::init().expect("gtk init");
        let block_list = gtk4::Box::new(gtk4::Orientation::Vertical, 0);
        let block_list_widget: &gtk4::Widget = block_list.upcast_ref();
        let notice = gtk4::Box::new(gtk4::Orientation::Vertical, 0);
        notice.add_css_class("block-finished");
        notice.add_css_class("block-assistant");
        notice.add_css_class("command-review-standalone");
        notice.set_margin_top(4);
        notice.set_margin_start(8);
        let header = gtk4::Box::new(gtk4::Orientation::Horizontal, 0);
        header.add_css_class("block-header");
        header.set_margin_top(6);
        header.set_margin_start(12);
        notice.append(&header);
        let body = gtk4::Box::new(gtk4::Orientation::Vertical, 0);
        body.add_css_class("command-review-body");
        body.set_margin_start(12);
        body.set_margin_bottom(11);
        notice.append(&body);

        let mut config = Config::safe_defaults();
        config.block_compact = true;
        let block_list_mount = dock_mount_decision(notice.parent().as_ref(), block_list_widget);
        assert_eq!(block_list_mount, DockMount::Append);
        assert!(super::prepare_inline_notice_for_mount(
            notice.upcast_ref(),
            &config,
            block_list_mount,
        ));
        assert!(notice.has_css_class("block-compact"));
        assert_eq!(notice.margin_top(), 1);
        assert_eq!(notice.margin_start(), 4);
        assert_eq!(header.margin_top(), 3);
        assert_eq!(header.margin_start(), 8);
        assert_eq!(body.margin_start(), 8);
        assert_eq!(body.margin_bottom(), 7);

        // A direct integration card follows the dock boundary without first
        // passing through `insert_inline_notice`.
        let dock = gtk4::Box::new(gtk4::Orientation::Vertical, 0);
        let dock_widget: &gtk4::Widget = dock.upcast_ref();
        let integration = gtk4::Box::new(gtk4::Orientation::Vertical, 4);
        integration.add_css_class("block-finished");
        integration.add_css_class("block-assistant");
        integration.add_css_class("block-integration-notice");
        integration.set_margin_top(4);
        integration.set_margin_start(8);
        let integration_header = gtk4::Box::new(gtk4::Orientation::Horizontal, 8);
        integration_header.add_css_class("block-header");
        integration_header.set_margin_top(6);
        integration_header.set_margin_start(12);
        integration.append(&integration_header);

        let dock_mount = dock_mount_decision(integration.parent().as_ref(), dock_widget);
        assert_eq!(dock_mount, DockMount::Append);
        assert!(super::prepare_inline_notice_for_mount(
            integration.upcast_ref(),
            &config,
            dock_mount,
        ));
        assert!(integration.has_css_class("block-compact"));
        assert_eq!(integration.margin_top(), 1);
        assert_eq!(integration.margin_start(), 4);
        assert_eq!(integration_header.margin_top(), 3);
        assert_eq!(integration_header.margin_start(), 8);
    }

    /// The dock must never reparent a widget another region still owns: GTK
    /// would warn and the card would end up in neither place.
    #[test]
    #[ignore = "requires DISPLAY"]
    fn dock_mount_refuses_a_widget_another_region_owns() {
        use gtk4::prelude::*;

        gtk4::init().expect("gtk init");
        let dock = gtk4::Box::new(gtk4::Orientation::Vertical, 0);
        let elsewhere = gtk4::Box::new(gtk4::Orientation::Vertical, 0);
        let dock_widget: &gtk4::Widget = dock.upcast_ref();

        let card = gtk4::Label::new(Some("card"));
        let card_widget: gtk4::Widget = card.clone().upcast();
        assert_eq!(
            dock_mount_decision(card_widget.parent().as_ref(), dock_widget),
            DockMount::Append,
            "an unparented card is taken by the dock"
        );

        dock.append(&card);
        assert_eq!(
            dock_mount_decision(card_widget.parent().as_ref(), dock_widget),
            DockMount::Keep,
            "a docked card stays where it is; the dock is already beside the prompt"
        );

        dock.remove(&card);
        elsewhere.append(&card);
        assert_eq!(
            dock_mount_decision(card_widget.parent().as_ref(), dock_widget),
            DockMount::Refuse,
            "a card the scrolling document owns is refused, not stolen"
        );

        // Rejection is observational: a compact pane must not repaint or move
        // a roomy assistant widget which another container still owns.
        let rejected = gtk4::Box::new(gtk4::Orientation::Vertical, 0);
        rejected.add_css_class("block-assistant");
        rejected.set_margin_top(4);
        rejected.set_margin_start(8);
        elsewhere.append(&rejected);
        let decision = dock_mount_decision(rejected.parent().as_ref(), dock_widget);
        let mut compact = Config::safe_defaults();
        compact.block_compact = true;
        assert!(!super::prepare_inline_notice_for_mount(
            rejected.upcast_ref(),
            &compact,
            decision,
        ));
        assert!(!rejected.has_css_class("block-compact"));
        assert_eq!(rejected.margin_top(), 4);
        assert_eq!(rejected.margin_start(), 8);
    }

    #[test]
    #[ignore = "requires DISPLAY"]
    fn unified_search_capture_real_vte_uses_half_open_column_boundary() {
        use gtk4::prelude::*;
        use std::time::{Duration, Instant};
        use vte4::TerminalExt;

        gtk4::init().expect("gtk init");
        let terminal = vte4::Terminal::new();
        terminal.set_size(5, 2);
        let window = gtk4::Window::new();
        window.set_child(Some(&terminal));
        window.present();
        terminal.feed(b"ABCDE");
        let context = gtk4::glib::MainContext::default();
        let started = Instant::now();
        while started.elapsed() < Duration::from_millis(100) {
            while context.iteration(false) {}
            std::thread::sleep(Duration::from_millis(2));
        }

        let mut spans = Vec::new();
        let captured = capture_vte_rows_bounded(
            0,
            0,
            5,
            4,
            || false,
            |span| {
                spans.push(span);
                super::capture_vte_text_range(
                    &terminal,
                    span.start_row,
                    0,
                    span.end_row,
                    span.end_col,
                )
            },
        );
        assert_eq!(spans.len(), 1);
        assert_eq!(spans[0].end_col, 4);
        assert_eq!(spans[0].work_cells, 4);
        assert_eq!(captured.text, "ABCD");
        assert!(captured.incomplete);
    }

    #[test]
    fn lazy_finalize_payload_materializes_and_strips_exactly_once() {
        let output = Rc::new(RefCell::new(BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES)));
        output.borrow_mut().append(b"\x1b[32mhello\x1b[0m\r\n");
        let payload = super::LazyBlockRenderPayload::new(
            "$ ".to_string(),
            super::CapturedFinalizeOutput::Foreground(output),
        );

        assert_eq!(payload.materialization_count(), 0);
        assert_eq!(payload.materialize().output_plain, "hello\n");
        assert_eq!(
            payload.materialize().output_with_ansi,
            "\x1b[32mhello\x1b[0m\r\n"
        );
        assert_eq!(
            payload.materialization_count(),
            1,
            "all consumers share one raw/plain snapshot"
        );
    }

    #[test]
    fn accessor_snapshot_is_bounded_and_survives_prior_materialization() {
        let output = Rc::new(RefCell::new(BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES)));
        output.borrow_mut().append(b"\x1b[32mhello\x1b[0m\r\n");
        let payload = super::LazyBlockRenderPayload::new(
            "$ ".to_string(),
            super::CapturedFinalizeOutput::Foreground(output.clone()),
        );

        let snapshot = payload
            .output_snapshot(MAX_ZONE_SNAPSHOT_BYTES)
            .expect("captured output");
        assert_eq!(snapshot.plain, "hello");
        assert!(!snapshot.truncated);
        assert_eq!(
            payload.materialization_count(),
            0,
            "the bounded path never materializes the card payload"
        );
        assert!(
            !output.borrow().is_empty(),
            "the engine-owned ring is left for later consumers"
        );

        // A journal observer may materialize first; the snapshot then comes
        // from the memoized plain text under the same tail bound.
        payload.materialize();
        let snapshot = payload.output_snapshot(3).expect("memoized output");
        assert_eq!(snapshot.plain, "lo");
        assert!(snapshot.truncated);
        assert_eq!(payload.materialization_count(), 1);

        let empty = super::LazyBlockRenderPayload::new(
            String::new(),
            super::CapturedFinalizeOutput::Background(BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES)),
        );
        assert_eq!(empty.output_snapshot(MAX_ZONE_SNAPSHOT_BYTES), None);
    }

    #[test]
    fn journal_capability_and_correlation_gate_lazy_output() {
        let make_payload = || {
            let output = Rc::new(RefCell::new(BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES)));
            output
                .borrow_mut()
                .append(b"\x1b[32mjournal text\x1b[0m\r\n");
            super::LazyBlockRenderPayload::new(
                String::new(),
                super::CapturedFinalizeOutput::Foreground(output),
            )
        };

        for (lifecycle, enabled) in [(None, true), (Some(jsh_lifecycle("jsh-id")), false)] {
            let payload = make_payload();
            let mut submitted = false;
            super::submit_lazy_output_to_journal(lifecycle, enabled, &payload, |_, _| {
                submitted = true;
            });
            assert!(!submitted);
            assert_eq!(payload.materialization_count(), 0);
        }

        let payload = make_payload();
        let mut submitted = None;
        super::submit_lazy_output_to_journal(
            Some(jsh_lifecycle("jsh-id")),
            true,
            &payload,
            |lifecycle, text| submitted = Some((lifecycle, text.to_string())),
        );
        assert_eq!(
            submitted,
            Some((jsh_lifecycle("jsh-id"), "journal text".to_string()))
        );
        assert_eq!(payload.materialization_count(), 1);
        assert_eq!(
            payload.materialize().output_plain,
            "journal text\n",
            "a later observer shares the journal's memoized snapshot"
        );
        assert_eq!(payload.materialization_count(), 1);
    }

    // ── Dynamic OSC 10/11/12 color tracking ──────────────────────────────

    /// Resolve one query the way the reader callback does: dynamic override
    /// when present, theme color otherwise.
    fn color_reply(dynamic: &DynamicColors, kind: ColorKind, theme: RGBA) -> String {
        format_color_query_reply(kind, dynamic.get(kind).unwrap_or(theme))
    }

    #[test]
    fn dynamic_color_set_changes_query_reply() {
        let theme_bg = RGBA::parse("#121616").unwrap();
        let mut dynamic = DynamicColors::default();

        // Untouched tracker: the query reports the theme color.
        assert_eq!(
            color_reply(&dynamic, ColorKind::Background, theme_bg),
            "\x1b]11;rgb:1212/1616/1616\x1b\\"
        );

        // OSC 11 set (X11 rgb: form): the next query reports the dynamic color.
        dynamic.set(ColorKind::Background, "rgb:1e1e/2e2e/3e3e");
        assert_eq!(
            color_reply(&dynamic, ColorKind::Background, theme_bg),
            "\x1b]11;rgb:1e1e/2e2e/3e3e\x1b\\"
        );

        // Hex form updates the same slot; other slots stay on the theme.
        dynamic.set(ColorKind::Background, "#ff8800");
        assert_eq!(
            color_reply(&dynamic, ColorKind::Background, theme_bg),
            "\x1b]11;rgb:ffff/8888/0000\x1b\\"
        );
        assert_eq!(dynamic.get(ColorKind::Foreground), None);
        assert_eq!(dynamic.get(ColorKind::Cursor), None);
    }

    #[test]
    fn dynamic_color_reset_restores_theme_reply() {
        let theme_fg = RGBA::parse("#f8f7e9").unwrap();
        let mut dynamic = DynamicColors::default();

        dynamic.set(ColorKind::Foreground, "rgb:ffff/0000/0000");
        assert_eq!(
            color_reply(&dynamic, ColorKind::Foreground, theme_fg),
            "\x1b]10;rgb:ffff/0000/0000\x1b\\"
        );

        // OSC 110: the tracked value drops, queries answer the theme again.
        dynamic.reset(ColorKind::Foreground);
        assert_eq!(dynamic.get(ColorKind::Foreground), None);
        assert_eq!(
            color_reply(&dynamic, ColorKind::Foreground, theme_fg),
            "\x1b]10;rgb:f8f8/f7f7/e9e9\x1b\\"
        );
    }

    #[test]
    fn dynamic_color_junk_spec_is_ignored() {
        let mut dynamic = DynamicColors::default();
        dynamic.set(ColorKind::Background, "definitely-not-a-color!!");
        assert_eq!(dynamic, DynamicColors::default());

        // A junk set must not clobber a previously tracked value either.
        dynamic.set(ColorKind::Background, "rgb:0000/8888/ffff");
        let tracked = dynamic;
        dynamic.set(ColorKind::Background, "rgb:zz/zz/zz");
        dynamic.set(ColorKind::Background, "rgb:1/2");
        dynamic.set(ColorKind::Background, "rgb:1/2/3/4");
        dynamic.set(ColorKind::Background, "rgb:12345/1/1");
        dynamic.set(ColorKind::Background, "");
        assert_eq!(dynamic, tracked);

        // Palette sets are VTE-native and never tracked.
        dynamic.set(ColorKind::Palette(3), "#ffffff");
        assert_eq!(dynamic, tracked);
        assert_eq!(dynamic.get(ColorKind::Palette(3)), None);
    }

    #[test]
    fn color_spec_parses_x11_rgb_scaling_and_names() {
        // 1/2/4-digit channels each scale against their own width: `f`, `ff`,
        // and `ffff` all mean the full-intensity channel (XParseColor rules).
        let full = parse_color_spec("rgb:f/ff/ffff").unwrap();
        assert_eq!((full.red(), full.green(), full.blue()), (1.0, 1.0, 1.0));
        // Named and hex forms fall through to gdk's parser.
        assert_eq!(parse_color_spec("red"), RGBA::parse("#ff0000").ok());
        assert!(parse_color_spec(" #0af ").is_some());
        assert_eq!(parse_color_spec("nonsense"), None);
    }

    #[test]
    fn notification_rate_limit_spacing() {
        use std::time::{Duration, Instant};
        let start = Instant::now();
        // First notification ever is always allowed.
        assert!(notification_allowed(None, start));
        // A burst right after the first one is dropped...
        assert!(!notification_allowed(Some(start), start));
        assert!(!notification_allowed(
            Some(start),
            start + Duration::from_millis(1999)
        ));
        // ...until the two-second window has fully elapsed.
        assert!(notification_allowed(
            Some(start),
            start + Duration::from_secs(2)
        ));
        assert!(notification_allowed(
            Some(start),
            start + Duration::from_secs(5)
        ));
    }

    #[test]
    fn background_output_requires_visible_text() {
        assert!(!background_output_has_visible_text(b"\r\n\x1b[0m"));
        assert!(background_output_has_visible_text(
            b"\x1b[36mworker finished\x1b[0m\r\n"
        ));
        assert!(background_output_has_visible_text(b"visible\rhidden"));
        assert!(!background_output_has_visible_text(b"visible\r\x1b[2K"));
        assert!(!background_output_has_visible_text(
            b"\x1b]8;;https://example.invalid\x1b\\\x1b]8;;\x1b\\"
        ));
        assert!(background_output_has_visible_text(b"\xff\xfe"));
        assert!(!background_output_has_visible_text(
            b"invalid:\xff\xfe\r\x1b[2K"
        ));
    }

    #[test]
    fn taking_background_output_drains_the_pending_buffer() {
        let mut pending = BoundedByteRing::new(MAX_RAW_OUTPUT_BYTES);
        pending.append(b"async line\r\n");
        let mut taken = take_background_output(&mut pending).expect("visible output");
        assert_eq!(taken.make_contiguous(), b"async line\r\n");
        assert!(pending.is_empty());
        assert!(take_background_output(&mut pending).is_none());
    }

