    /// `cmd_truncated=1` is its own case: the shell *had* a command line and said
    /// so, which is worth distinguishing from a shell that sends no metadata at
    /// all. The reconstruction still wins when it captured something.
    #[test]
    fn a_truncated_command_line_is_labelled_not_guessed() {
        let meta = CommandMeta {
            command: None,
            command_truncated: true,
            ..CommandMeta::default()
        };
        assert_eq!(
            resolve_command_for_block(&meta, ""),
            (
                TRUNCATED_COMMAND_PLACEHOLDER.to_string(),
                super::CommandTextSource::ScreenAfterTruncation
            )
        );
        assert_eq!(
            resolve_command_for_block(&meta, "ls"),
            (
                "ls".to_string(),
                super::CommandTextSource::ScreenAfterTruncation
            )
        );
    }

    /// A packet carrying both a command prefix and `cmd_truncated=1` is
    /// self-contradictory. `ShellReported` is what makes `command_exact` true
    /// on the persisted record and unlocks agent replay of the text as written,
    /// so the prefix must never reach it — whatever else the packet claims.
    #[test]
    fn a_truncated_packet_never_reports_its_prefix_as_the_exact_command() {
        let contradictory = CommandMeta {
            command: Some("git commit -m \"the first eighty".to_string()),
            command_truncated: true,
            ..CommandMeta::default()
        };
        assert_eq!(
            resolve_command_for_block(&contradictory, "git commit -m \"the first eighty bytes\""),
            (
                "git commit -m \"the first eighty bytes\"".to_string(),
                super::CommandTextSource::ScreenAfterTruncation
            ),
            "the screen scrape may well be whole; the prefix is known not to be"
        );
        assert_eq!(
            resolve_command_for_block(&contradictory, ""),
            (
                TRUNCATED_COMMAND_PLACEHOLDER.to_string(),
                super::CommandTextSource::ScreenAfterTruncation
            ),
            "with nothing on screen the record says so, rather than showing half a command"
        );

        // The same text without the disclosure is still the exact command.
        let honest = CommandMeta {
            command_truncated: false,
            ..contradictory
        };
        assert_eq!(
            resolve_command_for_block(&honest, "").1,
            super::CommandTextSource::ShellReported
        );
    }

    /// jsh attaches the duration to `D` and the id to `C`; folding the two marks
    /// must not let the second one erase what the first carried.
    #[test]
    fn command_metadata_merges_across_both_marks() {
        let mut pending = PendingCommandMeta::from_command_start(&CommandMeta {
            id: Some("jsh-7".to_string()),
            cwd: Some("/tmp/project".to_string()),
            ..CommandMeta::default()
        });
        pending.merge_command_end(&CommandMeta {
            id: Some("jsh-7".to_string()),
            duration_ms: Some(1234),
            // jsh's D packet reports the cwd *after* the command; a `cd` must not
            // relabel the block with the directory it moved to.
            cwd: Some("/tmp/elsewhere".to_string()),
            ..CommandMeta::default()
        });
        assert_eq!(pending.id.as_deref(), Some("jsh-7"));
        assert_eq!(pending.cwd.as_deref(), Some("/tmp/project"));
        assert_eq!(pending.duration_ms, Some(1234));
        assert_eq!(
            pending.command_end_correlation(&CommandMeta {
                id: Some("jsh-7".to_string()),
                ..CommandMeta::default()
            }),
            CommandIdCorrelation::MatchedUntrusted
        );

        assert_eq!(
            PendingCommandMeta::default().command_end_correlation(&CommandMeta::default()),
            CommandIdCorrelation::Bare
        );
        assert_eq!(
            pending.command_end_correlation(&CommandMeta {
                id: Some("jsh-8".to_string()),
                ..CommandMeta::default()
            }),
            CommandIdCorrelation::Mismatch
        );
        assert_eq!(
            pending.command_end_correlation(&CommandMeta::default()),
            CommandIdCorrelation::Mismatch
        );
        let invalid_start = PendingCommandMeta::from_command_start(&CommandMeta {
            id: Some("bad/id".to_string()),
            ..CommandMeta::default()
        });
        assert_eq!(
            invalid_start.command_end_correlation(&CommandMeta {
                id: Some("also bad/id".to_string()),
                ..CommandMeta::default()
            }),
            CommandIdCorrelation::Mismatch,
            "invalid raw ids must not collapse into the bare-marker case"
        );

        // A shell that only labels its D mark still gets a cwd.
        let mut only_end = PendingCommandMeta::from_command_start(&CommandMeta::default());
        only_end.merge_command_end(&CommandMeta {
            cwd: Some("/srv".to_string()),
            ..CommandMeta::default()
        });
        assert_eq!(only_end.cwd.as_deref(), Some("/srv"));

        let rejected = PendingCommandMeta::from_command_start(&CommandMeta {
            id: Some("bad/id".to_string()),
            cwd: Some("/tmp/safe\u{202e}fake".to_string()),
            ..CommandMeta::default()
        });
        assert_eq!(rejected.id, None);
        assert_eq!(rejected.cwd, None);
    }

    /// A jsh `C` mark exactly as the shell emits it: all four identity slots
    /// on the one packet. Core's parser accepts `session_id`, `seq` and
    /// `started_at_ms` only on `C`, and `ExecutionLifecycle::from_command_meta`
    /// refuses anything less, so this is the only shape that mints a token.
    fn jsh_command_start(id: &str) -> CommandMeta {
        CommandMeta {
            id: Some(id.to_string()),
            session_id: Some("probe-session-1".to_string()),
            seq: Some(1),
            started_at_ms: Some(1_788_571_993_465),
            ..CommandMeta::default()
        }
    }

    fn jsh_lifecycle(id: &str) -> ExecutionLifecycle {
        ExecutionLifecycle::from_command_meta(&jsh_command_start(id))
            .expect("a complete C envelope mints a lifecycle")
    }

    /// The journal capability exists only for a complete `C` envelope, and only
    /// for an id jsh itself minted. Every incomplete or foreign shape here
    /// would previously have journaled captured output under a bare id.
    #[test]
    fn journal_lifecycle_requires_a_complete_jsh_start_envelope() {
        let start = jsh_command_start("jsh-b8c6-1");
        let pending = PendingCommandMeta::from_command_start(&start);
        assert_eq!(
            pending.journal_lifecycle().map(ExecutionLifecycle::id),
            Some("jsh-b8c6-1")
        );

        // Each identity slot is load-bearing on its own: jsh sends all four on
        // C, so a packet missing one is not jsh's and must not be journaled.
        for drop_slot in [
            |meta: &mut CommandMeta| meta.session_id = None,
            |meta: &mut CommandMeta| meta.seq = None,
            |meta: &mut CommandMeta| meta.started_at_ms = None,
            |meta: &mut CommandMeta| meta.id = None,
        ] {
            let mut partial = jsh_command_start("jsh-b8c6-1");
            drop_slot(&mut partial);
            assert!(
                PendingCommandMeta::from_command_start(&partial)
                    .journal_lifecycle()
                    .is_none(),
                "a partial C envelope must not mint a journal capability"
            );
        }

        // A shell that is not jsh has no journal Start to attach to.
        assert!(
            PendingCommandMeta::from_command_start(&jsh_command_start("other-shell-1"))
                .journal_lifecycle()
                .is_none()
        );
    }

    /// The `D` mark may corroborate the identity, never mint or replace it.
    /// Core's parser drops the three Start-only slots on `D`, and this pins
    /// forge's own half of that rule against a hand-built full packet.
    #[test]
    fn command_end_neither_mints_nor_replaces_the_journal_lifecycle() {
        let mut bare = PendingCommandMeta::from_command_start(&CommandMeta {
            id: Some("jsh-b8c6-1".to_string()),
            ..CommandMeta::default()
        });
        bare.merge_command_end(&jsh_command_start("jsh-b8c6-1"));
        assert!(
            bare.journal_lifecycle().is_none(),
            "a D packet must never complete an envelope the C mark left partial"
        );

        let mut started = PendingCommandMeta::from_command_start(&jsh_command_start("jsh-b8c6-1"));
        started.merge_command_end(&jsh_command_start("jsh-forged-9"));
        assert_eq!(
            started.journal_lifecycle().map(ExecutionLifecycle::id),
            Some("jsh-b8c6-1"),
            "a D packet must never overwrite the capability the C mark minted"
        );

        // The finalize path clears the capability when D names a different
        // execution: the token then points at some other command's record.
        started.forget_correlated_identity();
        assert!(started.journal_lifecycle().is_none());
        assert!(started.id.is_none());
    }

    #[test]
    fn private_shell_token_distinguishes_trusted_command_ids() {
        let token = "0123456789abcdef0123456789abcdef";
        assert!(command_id_uses_shell_token(
            "0123456789abcdef0123456789abcdef-7",
            token
        ));
        assert!(!command_id_uses_shell_token(token, token));
        assert!(!command_id_uses_shell_token("jsh-7", token));

        let start = CommandMeta {
            id: Some(format!("{token}-7")),
            ..CommandMeta::default()
        };
        let end = CommandMeta {
            id: start.id.clone(),
            ..CommandMeta::default()
        };
        assert_eq!(
            PendingCommandMeta::from_command_start_with_token(&start, token)
                .command_end_correlation(&end),
            CommandIdCorrelation::MatchedTrusted
        );
        assert!(
            PendingCommandMeta::from_command_start_with_token(&start, token)
                .journal_lifecycle()
                .is_none(),
            "private shell tokens must never reach the persistent jsh journal"
        );
        assert_eq!(
            PendingCommandMeta::from_command_start(&start).command_end_correlation(&end),
            CommandIdCorrelation::MatchedUntrusted
        );
        // Same rule against a *complete* envelope. forge's own shims emit only
        // `id=`, so today the envelope filter would already refuse this, but
        // the secret filter must not lean on that: the token is the pane
        // secret, and the journal is a durable file every app here reads back.
        let token_start = jsh_command_start(&format!("{token}-7"));
        assert!(
            !journal_lifecycle_provenance_admits(
                &ExecutionLifecycle::from_command_meta(&token_start)
                    .expect("the envelope itself is complete"),
                token
            ),
            "a complete envelope keyed by the pane secret is still refused"
        );
        assert!(
            PendingCommandMeta::from_command_start_with_token(&token_start, token)
                .journal_lifecycle()
                .is_none()
        );
        // Isolate the secret filter from the `jsh-` provenance filter, so a
        // token that happened to look like a jsh id could not slip past on the
        // prefix alone. The same id is admitted in a pane that issued no token.
        let jsh_shaped_token = "jsh-0123456789abcdef";
        let disguised = jsh_lifecycle(&format!("{jsh_shaped_token}-7"));
        assert!(!journal_lifecycle_provenance_admits(
            &disguised,
            jsh_shaped_token
        ));
        assert!(journal_lifecycle_provenance_admits(&disguised, ""));

        let jsh = PendingCommandMeta::from_command_start(&jsh_command_start("jsh-session-7"));
        assert_eq!(
            jsh.journal_lifecycle().map(ExecutionLifecycle::id),
            Some("jsh-session-7")
        );
    }

    #[test]
    fn shell_integration_capability_requires_the_exact_private_handshake() {
        let ready = Cell::new(false);
        let token = "0123456789abcdef0123456789abcdef";
        assert!(!accept_agent_integration_token(
            BlockState::CollectingPrompt,
            token,
            "wrong",
            &ready
        ));
        assert!(!ready.get());
        assert!(!accept_agent_integration_token(
            BlockState::CollectingPrompt,
            "",
            token,
            &ready
        ));
        assert!(!ready.get());
        for state in [
            BlockState::Idle,
            BlockState::AwaitingCommand,
            BlockState::CollectingOutput,
        ] {
            assert!(!accept_agent_integration_token(state, token, token, &ready));
            assert!(!ready.get());
        }
        assert!(accept_agent_integration_token(
            BlockState::CollectingPrompt,
            token,
            token,
            &ready
        ));
        assert!(ready.get());
    }

    #[test]
    fn shell_integration_notice_only_offers_honest_direct_shell_fixes() {
        let argv = |values: &[&str]| {
            values
                .iter()
                .map(|value| (*value).to_string())
                .collect::<Vec<_>>()
        };
        for (command, shell, rc, load) in [
            (
                "/bin/bash",
                "bash",
                "~/.bashrc",
                "source <(forge --shell-integration bash)",
            ),
            (
                "zsh",
                "zsh",
                "${ZDOTDIR:-$HOME}/.zshrc",
                "source <(forge --shell-integration zsh)",
            ),
            (
                "/usr/bin/fish",
                "fish",
                "~/.config/fish/config.fish",
                "forge --shell-integration fish | source",
            ),
            (
                "pwsh",
                "pwsh",
                "$PROFILE",
                "forge --shell-integration pwsh | Out-String | Invoke-Expression",
            ),
        ] {
            let hint = shell_integration_hint(&argv(&[command])).expect(command);
            assert_eq!(hint.shell, shell);
            assert_eq!(hint.rc, rc);
            assert_eq!(hint.load, load);
        }
        assert!(shell_integration_hint(&argv(&["bash", "-i"])).is_some());
        assert!(shell_integration_hint(&argv(&["bash", "-C", "-i"])).is_some());
        assert!(shell_integration_hint(&argv(&["zsh", "-i"])).is_some());
        assert!(shell_integration_hint(&argv(&["fish", "-i"])).is_some());
        assert!(shell_integration_hint(&argv(&["fish", "-C", "set -g fish_greeting"])).is_some());
        assert!(shell_integration_hint(&argv(&["pwsh", "-Interactive"])).is_some());
        assert!(!super::shell_argv_runs_one_command(&argv(&[
            "pwsh",
            "-ExecutionPolicy",
            "Bypass",
        ])));
        assert_eq!(
            shell_integration_hint(&argv(&["/usr/bin/powershell"]))
                .expect("powershell alias")
                .shell,
            "pwsh"
        );

        for unsupported in [
            argv(&["jsh"]),
            argv(&["/usr/local/bin/jsh", "-l"]),
            argv(&["bash", "-c", "ls"]),
            argv(&["bash", "--command", "ls"]),
            argv(&["bash", "-lc", "ls"]),
            argv(&["bash", "--norc"]),
            argv(&["bash", "--rcfile", "/tmp/custom.bashrc"]),
            argv(&["bash", "--init-file=/tmp/custom.bashrc"]),
            argv(&["bash", "--posix"]),
            argv(&["bash", "--", "script.sh"]),
            argv(&["bash", "script.sh"]),
            argv(&["bash", "-l"]),
            argv(&["zsh", "-f"]),
            argv(&["zsh", "-o", "norcs"]),
            argv(&["zsh", "+o", "rcs"]),
            argv(&["zsh", "--no_rcs"]),
            argv(&["zsh", "-t"]),
            argv(&["zsh", "script.zsh"]),
            argv(&["fish", "--no-config"]),
            argv(&["fish", "--command=echo ok"]),
            argv(&["fish", "--no-execute"]),
            argv(&["fish", "script.fish"]),
            argv(&["pwsh", "-NoProfile"]),
            argv(&["pwsh", "-NonInteractive"]),
            argv(&["pwsh", "-SSHServerMode"]),
            argv(&["pwsh", "-CommandWithArgs", "Get-Location"]),
            argv(&["pwsh", "-Command", "Get-Location"]),
            argv(&["powershell", "--Command", "Get-Location"]),
            argv(&["pwsh", "-EncodedCommand", "ZQB4AGkAdAA="]),
            argv(&["pwsh", "-File", "profile.ps1"]),
            argv(&["pwsh", "profile.ps1"]),
            argv(&["ssh", "build-host"]),
            argv(&["docker", "exec", "-it", "box", "bash"]),
            argv(&["flatpak-spawn", "--host", "bash"]),
            argv(&["sh"]),
            Vec::new(),
        ] {
            assert_eq!(
                shell_integration_hint(&unsupported),
                None,
                "{unsupported:?}"
            );
        }
    }

    #[test]
    fn agent_execution_shell_matrix_is_fail_closed() {
        let strings = |values: &[&str]| {
            values
                .iter()
                .map(|value| (*value).to_string())
                .collect::<Vec<_>>()
        };
        assert!(shell_argv_supports_agent_ids(&strings(&[
            "/bin/bash",
            "-l"
        ])));
        assert!(shell_argv_supports_agent_ids(&strings(&[
            "/bin/bash",
            "--rcfile",
            "/tmp/forge-rc",
            "-i",
        ])));
        assert!(shell_argv_supports_agent_ids(&strings(&[
            "zsh", "--no-rcs"
        ])));
        assert!(!shell_argv_supports_agent_ids(&strings(&[
            "bash", "-lc", "echo ok"
        ])));
        assert!(!shell_argv_supports_agent_ids(&strings(&[
            "zsh",
            "--command",
            "echo ok"
        ])));
        assert!(!shell_argv_supports_agent_ids(&strings(&["fish"])));
        assert!(!shell_argv_supports_agent_ids(&strings(&["pwsh"])));
        assert!(shell_argv_uses_jsh(&strings(&[
            "bash",
            "-lc",
            "exec /usr/bin/jsh"
        ])));
        assert!(!shell_argv_supports_agent_ids(&strings(&[
            "bash",
            "-lc",
            "exec /usr/bin/jsh",
        ])));
    }

    #[test]
    fn agent_command_end_requires_shell_ownership_and_consistent_ids() {
        assert_eq!(
            decide_agent_command_end(
                true,
                PtyForeground::Other,
                false,
                CommandIdCorrelation::Bare,
            ),
            AgentCommandEndDecision::IgnoreUntilShellOwnsForeground
        );
        assert_eq!(
            decide_agent_command_end(
                true,
                PtyForeground::Shell,
                false,
                CommandIdCorrelation::Bare,
            ),
            AgentCommandEndDecision::AcceptWithoutAgentCorrelation,
            "Agent observation requires a C/D execution id even when ordinary Block mode accepts bare markers"
        );
        for (foreground, typeahead, ids) in [
            (PtyForeground::Unknown, false, CommandIdCorrelation::Bare),
            (PtyForeground::Other, true, CommandIdCorrelation::Bare),
            (PtyForeground::Shell, false, CommandIdCorrelation::Mismatch),
        ] {
            assert_eq!(
                decide_agent_command_end(true, foreground, typeahead, ids),
                AgentCommandEndDecision::AcceptWithoutAgentCorrelation
            );
        }
        assert_eq!(
            decide_agent_command_end(
                true,
                PtyForeground::Shell,
                false,
                CommandIdCorrelation::MatchedTrusted,
            ),
            AgentCommandEndDecision::Accept
        );
        assert_eq!(
            decide_agent_command_end(
                false,
                PtyForeground::Other,
                false,
                CommandIdCorrelation::Mismatch,
            ),
            AgentCommandEndDecision::Accept,
            "ordinary Block mode keeps its compatibility behavior"
        );
    }

